/-- [The set](hyp:D) establish [the supplied set is contained in the closed unit interval](goal). -/
def IsUnitIntervalSubset (D : Set ℝ) : Prop :=
  D ⊆ Set.Icc (0 : ℝ) 1

/-- [The model](hyp:Mdl) establish [the proxy channel has column rank equal to the number of latent states](goal). -/
def ProxyChannelInjectivity (Mdl : LatentShiftSCM E U W X Y) : Prop :=
  Mdl.M.rank = Fintype.card U

/-- The paper's positive rank indices, bounded by the smaller matrix dimension. -/
def RankIndex (E W : Type*) [Fintype E] [Fintype W] :=
  {r0 : ℕ // 1 ≤ r0 ∧ r0 ≤ min (Fintype.card W) (Fintype.card E)}

/-- [The model, treatment, rank index](hyp:Mdl,x,r0) establish [the selected conditional proxy matrix has exactly the specified rank](goal). -/
def RegularFixedRank (Mdl : LatentShiftSCM E U W X Y) (x : X) (r0 : ℕ) : Prop :=
  (proxyMomentMatrix Mdl x).rank = r0

/-- [The model, treatment](hyp:Mdl,x) establish [the target proxy vector lies in the selected conditional proxy matrix's column space](goal). -/
def RegularTargetSpan (Mdl : LatentShiftSCM E U W X Y) (x : X) : Prop :=
  ∃ kappa, (proxyMomentMatrix Mdl x).mulVec kappa = targetProxyVector Mdl

/-- [The model](hyp:Mdl) establish [the target full law uses the source proxy, treatment, and outcome mechanisms while changing only the latent distribution](goal). -/
def TargetMechanismInvariance (Mdl : LatentShiftSCM E U W X Y) : Prop :=
  ∀ u w x y, Mdl.QM u w x y = Mdl.q u * Mdl.M w u * Mdl.a x u * Mdl.f x y u w

/-- [The proxy matrix, target proxy vector](hyp:Bx,bvec) determine [the set of source-environment weights whose proxy-moment image equals the target proxy vector](goal). -/
def balancingFiber (Bx : Matrix W E ℝ) (bvec : W → ℝ) : Set (E → ℝ) :=
  {lam | Bx.mulVec lam = bvec}

/-- [The observed law and target proxy vector](hyp:PO,bvec) determine [their compatible-model
fiber](goal): models [satisfy the positive latent-shift conditions](step:1), [match the observed
law](step:2), and [match the target proxy distribution](step:3). -/
def compatibleFiber (PO : E → W → X → Y → ℝ) (bvec : W → ℝ) :
    Set (LatentShiftSCM E U W X Y) :=
  {Mdl | PositiveLatentShiftClass Mdl ∧ observedLaw Mdl = PO ∧ targetProxyVector Mdl = bvec}

/-- [The environment type, proxy type](hyp:E,W) determine [the total number of proxy, outcome, and target coordinates controlled by the simultaneous concentration event](goal). -/
def coordinateCount (E W : Type*) [Fintype E] [Fintype W] : ℕ :=
  Fintype.card W * Fintype.card E + Fintype.card E + Fintype.card W

/-- [The proxy matrix and target proxy vector](hyp:Bx,bvec) determine [the failure-separator
set](goal): its vectors [annihilate the matrix on the left](step:1) but [have nonzero inner
product with the target vector](step:2). -/
def failureSeparator (Bx : Matrix W E ℝ) (bvec : W → ℝ) : Set (W → ℝ) :=
  {h | Bx.vecMul h = 0 ∧ dotProduct h bvec ≠ 0}

/-- The graph-truncated target functional: the treatment mechanism is deleted at fixed `x`. -/
def interventionalProb (Mdl : LatentShiftSCM E U W X Y) (x : X) (y : Y) : ℝ :=
  ∑ u, ∑ w, Mdl.q u * Mdl.M w u * Mdl.f x y u w

/-- [The model, treatment, outcome](hyp:Mdl,x,y) establish [the latent-state response probability after averaging the outcome mechanism over proxies](goal). -/
def latentResponse (Mdl : LatentShiftSCM E U W X Y) (x : X) (y : Y) : U → ℝ :=
  fun u => ∑ w, Mdl.M w u * Mdl.f x y u w

/-- [The model, separator](hyp:Mdl,h) determine [the proxy-channel pullback of a separator to latent-state coordinates](goal). -/
def latentSeparator (Mdl : LatentShiftSCM E U W X Y) (h : W → ℝ) : U → ℝ :=
  Mdl.M.vecMul h

/-- The observed source law after marginalizing the latent state. -/
def observedLaw (Mdl : LatentShiftSCM E U W X Y) : E → W → X → Y → ℝ :=
  fun e w x y => ∑ u, Mdl.PM e u w x y

/-- [The model, treatment, outcome](hyp:Mdl,x,y) determine [the environment-indexed unconditional treatment-and-outcome moment vector](goal). -/
def outcomeMomentVector (Mdl : LatentShiftSCM E U W X Y) (x : X) (y : Y) : E → ℝ :=
  (unconditionalBalancingMoments (observedLaw Mdl) x y).2

/-- [The model, treatment](hyp:Mdl,x) determine [the unconditional proxy-by-environment treatment-moment matrix](goal). -/
def proxyMomentMatrix (Mdl : LatentShiftSCM E U W X Y) (x : X) : Matrix W E ℝ :=
  fun w e => ∑ y, observedLaw Mdl e w x y

/-- [The point estimate, variance estimate, row index, row-size certificate, nominal level](hyp:thetaHat,Vhat,n,_hn,alpha) establish [the closed normal-quantile Wald interval centered at the estimate with its totalized nonnegative standard-error half-width](goal). -/
noncomputable def regularWaldInterval (thetaHat Vhat : ℝ) (n : ℕ) (_hn : 2 ≤ n)
    (alpha : Set.Ioo (0 : ℝ) 1) : Set ℝ :=
  let zcrit := Causalean.Mathlib.probit (1 - (alpha : ℝ) / 2)
  let halfWidth := zcrit * Real.sqrt (Vhat / n)
  Set.Icc (thetaHat - halfWidth) (thetaHat + halfWidth) ∩ Set.Icc (0 : ℝ) 1

/-- [The source sample size, target sample size](hyp:ns,nt) determine [the projection from the joint two-sample space onto its source-observation block](goal). -/
def sourceBlock (ns nt : ℕ) : Omega E W X Y ns nt → (Fin ns → E × W × X × Y) :=
  Prod.fst

/-- [The observed law](hyp:PO) establish [the flattened vector of full observed-law cell probabilities](goal). -/
def sourceCellVector (PO : E → W → X → Y → ℝ) : (E × W × X × Y) → ℝ :=
  fun o => PO o.1 o.2.1 o.2.2.1 o.2.2.2

/-- [The model, treatment](hyp:Mdl,x) establish [the source treatment probability in each environment](goal). -/
def sourceTreatmentProb (Mdl : LatentShiftSCM E U W X Y) (x : X) : E → ℝ :=
  fun e => ∑ u, Mdl.a x u * Mdl.S u e

/-- [The rank index, singular gap, positive floor, allocation fraction, treatment, outcome](hyp:r0,c,eta,p,x,y) establish [the set of positive models satisfying the specified rank, singular-gap, target-span, cell-floor, and variance-floor restrictions](goal). -/
def stronglyIdentifiedSubmodelSet (r0 : RankIndex E W) (c eta : ℝ)
    (p : Set.Ioo (0 : ℝ) 1) (x : X) (y : Y) :
    Set (LatentShiftSCM E U W X Y) :=
  {Mdl | StronglyIdentifiedSubmodel r0 c eta p x y Mdl}

/-- [The allocation fraction, treatment, source allocation, target allocation](hyp:p,x,ns,nt) establish [the class of positive two-sample arrays satisfying the specified allocation, row-law, sampling, and target-span conditions](goal). -/
def studentizedArrayClassSet (p : Set.Ioo (0 : ℝ) 1) (x : X) (ns nt : ℕ → ℕ) :
    Set (TwoSampleArray E U W X Y ns nt) :=
  {A | StudentizedArrayClass p x ns nt A}

/-- [The source sample size, target sample size](hyp:ns,nt) determine [the projection from the joint two-sample space onto its target-proxy block](goal). -/
def targetBlock (ns nt : ℕ) : Omega E W X Y ns nt → (Fin nt → W) :=
  Prod.snd

/-- The target proxy marginal, equivalently `M q` under the target factorization. -/
def targetProxyVector (Mdl : LatentShiftSCM E U W X Y) : W → ℝ :=
  fun w => ∑ u, Mdl.M w u * Mdl.q u
